"use client";

import React, { useState, useEffect } from "react";
import { BannerAnalyticItem } from "@/types/analytics";
import { fetchBannerAnalytics } from "@/services/analyticsService";
import { BannerCard } from "@/components/BannerCard";
import { BarChart3, Layers, MousePointerClick, Eye, Timer, RefreshCw } from "lucide-react";

export default function DashboardPage() {
  const [banners, setBanners] = useState<BannerAnalyticItem[]>([]);
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    setLoading(true);
    const data = await fetchBannerAnalytics();
    setBanners(data);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  // Overall totals
  const totalClicks = banners.reduce((acc, curr) => acc + curr.metrics.clickCount, 0);
  const totalViews = banners.reduce((acc, curr) => acc + curr.metrics.viewCount, 0);
  const avgOverallSeconds =
    banners.length > 0
      ? (banners.reduce((acc, curr) => acc + curr.metrics.avgSecondView, 0) / banners.length).toFixed(1)
      : "0";

  return (
    <main className="min-h-screen bg-slate-950 text-slate-100 pb-20">
      {/* Top Header */}
      <header className="border-b border-slate-800 bg-slate-900/60 sticky top-0 z-40 backdrop-blur-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-indigo-600 to-purple-500 flex items-center justify-center shadow-lg shadow-indigo-600/30">
              <BarChart3 className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="font-bold text-base sm:text-lg text-white leading-tight">
                HeyPlay Banner Analytics
              </h1>
              <p className="text-[11px] text-slate-400">
                Backend: <span className="text-indigo-400 font-mono">v2.heyplaymyanmar.com</span>
              </p>
            </div>
          </div>

          <button
            onClick={loadData}
            title="Reload Data"
            className="flex items-center gap-2 px-3.5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-xl text-xs font-medium transition-colors shadow-sm"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin text-indigo-400" : ""}`} />
            <span>Reload</span>
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8 space-y-8">
        {/* Metric Top Summary Bar */}
        <section className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="bg-slate-900/80 border border-slate-800 p-5 rounded-2xl flex items-center justify-between shadow-lg">
            <div>
              <div className="text-xs uppercase font-semibold text-slate-400 tracking-wider">
                Total Banner Clicks
              </div>
              <div className="text-3xl font-extrabold text-white mt-1">
                {totalClicks.toLocaleString()}
              </div>
              <p className="text-xs text-emerald-400 mt-1">Sum of all banner clicks</p>
            </div>
            <div className="p-3 bg-emerald-500/10 text-emerald-400 rounded-2xl border border-emerald-500/20">
              <MousePointerClick className="w-6 h-6" />
            </div>
          </div>

          <div className="bg-slate-900/80 border border-slate-800 p-5 rounded-2xl flex items-center justify-between shadow-lg">
            <div>
              <div className="text-xs uppercase font-semibold text-slate-400 tracking-wider">
                Total Views
              </div>
              <div className="text-3xl font-extrabold text-white mt-1">
                {totalViews.toLocaleString()}
              </div>
              <p className="text-xs text-blue-400 mt-1">User impressions registered</p>
            </div>
            <div className="p-3 bg-blue-500/10 text-blue-400 rounded-2xl border border-blue-500/20">
              <Eye className="w-6 h-6" />
            </div>
          </div>

          <div className="bg-slate-900/80 border border-slate-800 p-5 rounded-2xl flex items-center justify-between shadow-lg">
            <div>
              <div className="text-xs uppercase font-semibold text-slate-400 tracking-wider">
                Average View Duration
              </div>
              <div className="text-3xl font-extrabold text-amber-400 mt-1">
                {avgOverallSeconds} <span className="text-lg text-slate-300">sec</span>
              </div>
              <p className="text-xs text-amber-400/80 mt-1">Target ~3.0s view</p>
            </div>
            <div className="p-3 bg-amber-500/10 text-amber-400 rounded-2xl border border-amber-500/20">
              <Timer className="w-6 h-6" />
            </div>
          </div>
        </section>

        {/* Banner Details Listing */}
        <section className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Layers className="w-5 h-5 text-indigo-400" />
              <h2 className="text-lg font-bold text-white">Banners Performance</h2>
              <span className="text-xs bg-slate-800 text-slate-400 px-2.5 py-0.5 rounded-full font-mono">
                {banners.length} Banners
              </span>
            </div>
          </div>

          {loading ? (
            <div className="py-20 flex flex-col items-center justify-center gap-3 text-slate-400">
              <RefreshCw className="w-7 h-7 animate-spin text-indigo-400" />
              <p className="text-sm">Loading Banner Analytics data...</p>
            </div>
          ) : (
            <div className="space-y-4">
              {banners.map((banner) => (
                <BannerCard key={banner.id} banner={banner} />
              ))}
            </div>
          )}
        </section>
      </div>
    </main>
  );
}
